{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Rats given an oral extract containing chlorogenic acid, rutin, and hyperoside had these polyphenolic glycosides detected in brain, demonstrating that polar glycosylated polyphenols can achieve CNS access; the high transfer score and structural similarity to the baicalin glucuronide support applicability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Astragalin, a flavonoid 3-O-glucoside, was shown to transfer across the BBB in rat tissue distribution studies, directly supporting brain access for flavonoid glycosides like the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Hydroxysafflor yellow A, a highly polar multi-glycosylated polyphenol, reached 1026 ng/g in rat brain, showing that even very polar polyphenolic glycosides can achieve meaningful brain concentrations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Cyanidin 3-glucoside was detected in human brain and in rat brain after blueberry feeding or intravenous administration, providing human-relevant evidence that anthocyanin glycosides cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Agnuside, a glycoside natural product, was detected in mouse brain within 24 h, indicating effective BBB crossing and retention for glycoside-type compounds.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. Multiple high-transfer in vivo studies show that polar glycosylated polyphenols and related natural products are detected in brain after systemic administration. The query, baicalin, is a flavonoid 7-O-glucuronide sharing these features and is expected to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct quantitative brain/plasma or CSF measurement for baicalin itself is provided.",
    "Possible contribution of aglycone or metabolite formation to brain detection is not fully excluded.",
    "Efflux liability for the glucuronide moiety is not directly quantified, though meaningful access does not require absence of efflux."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

